"""AI generated draft models enforcing human-in-the-loop confirmation.

Every AI proposal starts in PENDING_CONFIRMATION status and must carry a
mandatory medical disclaimer to confirm all details with a doctor or pharmacist.
"""

from enum import Enum
from typing import Any, Dict, Optional

from pydantic import BaseModel, Field


class DraftType(str, Enum):
    """Type of draft extracted or generated by Gemini AI."""

    MEDICATION = "MEDICATION"
    APPOINTMENT = "APPOINTMENT"
    WHY_AM_I_TAKING_THIS = "WHY_AM_I_TAKING_THIS"
    DOCTOR_BRIEFING = "DOCTOR_BRIEFING"


class DraftStatus(str, Enum):
    """Lifecycle status of an AI-generated draft."""

    PENDING_CONFIRMATION = "PENDING_CONFIRMATION"
    CONFIRMED = "CONFIRMED"
    REJECTED = "REJECTED"


class ParseNoteRequest(BaseModel):
    """Input request containing doctor notes or caregiver instructions for AI parsing."""

    raw_text: str = Field(
        ...,
        min_length=5,
        max_length=5000,
        description="Prescription note or doctor discharge summary",
    )


class PrescriptionPhotoRequest(BaseModel):
    """Payload for uploading or submitting a prescription photo/label for AI extraction."""

    image_base64: str = Field(
        ...,
        min_length=10,
        description="Base64-encoded prescription image data",
    )
    mime_type: str = Field(default="image/jpeg", description="MIME type (image/jpeg, image/png, image/webp)")
    elder_id: Optional[str] = Field(default="elder_1", description="Associated elder profile ID")


class VoiceOrNaturalLanguageRequest(BaseModel):
    """Input payload for natural language voice notes or colloquial speech transcripts."""

    text: str = Field(
        ...,
        min_length=3,
        max_length=5000,
        description="Transcribed voice recording or conversational message",
    )
    elder_id: Optional[str] = Field(default="elder_1", description="Associated elder profile ID")


class WhyAmITakingThisRequest(BaseModel):
    """Request for a plain-language senior-friendly explanation of why a medication is prescribed."""

    medication_name: str = Field(..., min_length=1, max_length=120)
    dosage: Optional[str] = Field(default=None, max_length=100)
    medication_id: Optional[str] = Field(default=None, description="Optional medication ID in database")
    elder_id: Optional[str] = Field(default="elder_1", description="Associated elder profile ID")


class DoctorBriefingRequest(BaseModel):
    """Request to generate a concise pre-appointment clinical briefing from adherence history."""

    elder_id: str = Field(default="elder_1", description="Target elder profile ID")
    appointment_id: Optional[str] = Field(default=None, description="Optional upcoming appointment ID")
    timeframe_days: int = Field(default=14, ge=1, le=90, description="Adherence lookback period in days")


class AIDraft(BaseModel):
    """AI-suggested draft waiting for mandatory human confirmation before saving."""

    id: str
    elder_id: str
    draft_type: DraftType
    status: DraftStatus = DraftStatus.PENDING_CONFIRMATION
    source_snippet: str
    proposed_data: Dict[str, Any]
    reasoning: str
    medical_disclaimer: str = Field(
        default="Medical Notice: This is an AI-generated draft. Please confirm all details with your doctor or pharmacist.",
        description="Mandatory medical advisory disclaimer",
    )
    created_at: str
    confirmed_at: Optional[str] = None
    confirmed_by: Optional[str] = None


class ConfirmDraftRequest(BaseModel):
    """Human confirmation or rejection decision on an AI draft."""

    approved: bool = Field(
        ...,
        description="True to confirm and commit to database, False to reject",
    )
    modifications: Optional[Dict[str, Any]] = Field(
        default=None,
        description="Optional human edits applied prior to final confirmation",
    )
